#include <iostream>
#include <vector>
#include <cmath>
#include <conio.h>
#include <windows.h>
// RAFT 2.0 3D (software-projected): ocean plane + raft cubes + barrels + shark
struct V{double x,y,z;};struct E{int a,b;};
int main(){double _yaw=0,_px=1,_pz=1,_w=6;std::vector<V>_cube={-1,-.2,-1,1,-.2,-1,1,.2,-1,-1,.2,-1,-1,-.2,1,1,-.2,1,1,.2,1,-1,.2,1};int _E[][2]={{0,1},{1,2},{2,3},{3,0},{4,5},{5,6},{6,7},{7,4},{0,4},{1,5},{2,6},{3,7}};std::vector<std::pair<double,double>>_raft={{0,0},{2,0},{0,2},{2,2}};std::vector<std::pair<double,double>>_bar;for(int i=0;i<10;i++)_bar.push_back({(rand()%40-20),(rand()%40-20)});double _sx=10,_sz=8;const int W=80,H=25;auto _pj=[&](double wx,double wy,double wz,int&W,int&H,int&sx,int&sy)->bool{double dx=wx-_px,dz=wz-_pz,dy=wy-1.5;double c=cos(_yaw),s=sin(_yaw);double x1=dx*c-dz*s,z1=dx*s+dz*c;z1+=8;if(z1<.5)return 0;double f=30/z1;sx=(int)(W/2+x1*f);sy=(int)(H/2-dy*f);return sx>=0&&sx<W&&sy>=0&&sy<H;};std::cout<<"RAFT 2.0 3D: WASD move J/L turn B build Q quit\n";while(true){if(_kbhit()){char k=_getch();if(k=='q')break;double c=cos(_yaw),s=sin(_yaw);if(k=='w'){_px-=s;_pz-=c;}if(k=='s'){_px+=s;_pz+=c;}if(k=='a'){_px-=c;_pz+=s;}if(k=='d'){_px+=c;_pz-=s;}if(k=='j')_yaw+=.15;if(k=='l')_yaw-=.15;if(k=='b'&&_w>=4){_w-=4;_raft.push_back({_px+3,_pz});}for(int i=_bar.size()-1;i>=0;i--){if(fabs(_bar[i].first-_px)<1.5&&fabs(_bar[i].second-_pz)<1.5){_w++;_bar[i]={(double)(rand()%40-20+_px),(double)(rand()%40-20+_pz)};}}}_sx+=(_px-_sx)*.02;_sz+=(_pz-_sz)*.02;if(fabs(_sx-_px)+fabs(_sz-_pz)<3&&_raft.size()>1&&rand()%20==0){_raft.pop_back();std::cout<<"SHARK ATE RAFT!\n";Sleep(300);}char g[25][81];for(int y=0;y<H;y++)for(int x=0;x<W;x++)g[y][x]=(y>H*2/3? '~':'.');for(auto&r:_raft){for(int e=0;e<12;e++)for(double t=0;t<=1;t+=.1){int i1=_E[e][0]*3,i2=_E[e][1]*3;double vx=_cube[i1]+(_cube[i2]-_cube[i1])*t+r.first,vy=_cube[i1+1]+(_cube[i2+1]-_cube[i1+1])*t+.2,vz=_cube[i1+2]+(_cube[i2+2]-_cube[i1+2])*t+r.second;int sx,sy;if(_pj(vx+.0,vy,vz,W,H,sx,sy))g[sy][sx]='#';}}for(auto&b:_bar){int sx,sy;if(_pj(b.first,.4,b.second,W,H,sx,sy))g[sy][sx]='B';}{int sx,sy;if(_pj(_sx,.3,_sz,W,H,sx,sy)&&sx>=0&&sx<W&&sy>=0&&sy<H)g[sy][sx]='S';}system("cls");for(int y=0;y<H;y++){g[y][W]=0;std::cout<<g[y]<<"\n";}std::cout<<"wood:"<<_w<<" raft:"<<_raft.size()<<" yaw:"<<_yaw<<"\n";Sleep(80);}return 0;}
